package domain

import (
	"crypto/sha256"
	"strings"
)

// APIKeyMinLength is the shortest access key the service accepts. Keys are
// generated by the platform operator from 256 bits of entropy.
const APIKeyMinLength = 16

// HashAPIKey returns the SHA-256 digest of an access key. Only the digest is
// stored, so a database dump does not reveal usable credentials. A fast hash
// is appropriate here because the key is high-entropy and machine generated,
// and the check is on the request hot path.
func HashAPIKey(raw string) []byte {
	sum := sha256.Sum256([]byte(strings.TrimSpace(raw)))
	return sum[:]
}

// ValidAPIKeyFormat performs the cheap shape check before touching storage.
func ValidAPIKeyFormat(raw string) bool {
	raw = strings.TrimSpace(raw)
	if len(raw) < APIKeyMinLength || len(raw) > 256 {
		return false
	}
	for _, r := range raw {
		if r <= ' ' || r > '~' {
			return false
		}
	}
	return true
}
